import LensManager, { ILensLayer } from "#core/ui/lenses/lens-manager.js";
import { HexToFloat4 } from "#core/ui/utilities/utilities-color.js";
import { getGlobalParamNumber } from "#core/ui/utilities/utilities-data.js";

import { OVERLAY_PRIORITY } from "#base/ui/utilities/utilities-overlay.js";

/**
 * Civ6 Appeal Lens colors
 * Breathtaking = 55,120,57 (#377839 strong green)
 * Charming		= 68, 135, 96 (#448760 lighter gray-green)
 * Average		= 94, 110, 125 (#5E6E7D gray)
 * Uninviting	= 135, 88, 47 (#87582F orange)
 * Disgusting	= 105, 34, 49 (#692231 dark red)
 */

const NATURAL_WONDER_COLOR = HexToFloat4(0x2010fd, 0.80);
const BREATHTAKING_COLOR = HexToFloat4(0x002000, 0.90);
const CHARMING_COLOR = HexToFloat4(0x155e09, 0.85);
const AVERAGE_COLOR = HexToFloat4(0x9b8181, 0.70);

export const ToggleGeneralAppealPanelEventName = "raise-general-appeal-panel";
export class ToggleGeneralAppealPanelEvent extends CustomEvent<{ enabled: boolean }> {
	constructor(enabled: boolean) {
		super(ToggleGeneralAppealPanelEventName, { bubbles: true, cancelable: true, detail: { enabled } });
	}
}

export class GeneralAppealLensLayer implements ILensLayer {
	private generalAppealOverlayGroup = WorldUI.createOverlayGroup(
		"GeneralAppealOverlayGroup",
		OVERLAY_PRIORITY.HEX_GRID,
	);
	private generalAppealOverlay = this.generalAppealOverlayGroup.addPlotOverlay();
	private naturalWonderPlots: PlotCoord[] = [];
	private breathtakingPlots: PlotCoord[] = [];
	private charmingPlots: PlotCoord[] = [];
	private averagePlots: PlotCoord[] = [];

	clearOverlay() {
		this.generalAppealOverlayGroup.clearAll();
		this.generalAppealOverlay.clear();

		this.naturalWonderPlots = [];
		this.breathtakingPlots = [];
		this.charmingPlots = [];
		this.averagePlots = [];
	}

	initLayer() {
		// nothing to initialize
	}

	applyLayer() {
		this.clearOverlay();
		const breathtakingThreshold = getGlobalParamNumber("APPEAL_FOR_DOUBLE_HAPPINESS_TILE_YIELD");
		const charmingThreshold = getGlobalParamNumber("APPEAL_FOR_HAPPINESS_TILE_YIELD");

		// Traverse the entire map and place plots in the appropriate "buckets".
		const width = GameplayMap.getGridWidth();
		const height = GameplayMap.getGridHeight();
		for (let x = 0; x < width; x++) {
			for (let y = 0; y < height; y++) {
				const isHidden = GameplayMap.getRevealedState(GameContext.localPlayerID, x, y) == RevealedStates.HIDDEN;
				if (isHidden) {
					continue;
				}

				// Natural wonders are special and get first crack at being set.
				if (GameplayMap.isNaturalWonder(x, y)) {
					this.naturalWonderPlots.push({ x, y });
				} else {
					// Not a natural wonder, use general appeal.
					const appeal = GameplayMap.getAppeal(x, y);
					if (appeal >= breathtakingThreshold) {
						this.breathtakingPlots.push({ x, y });
					} else if (appeal >= charmingThreshold) {
						this.charmingPlots.push({ x, y });
					} else if (!GameplayMap.isWater(x, y)) {
						this.averagePlots.push({ x, y });
					}
				}
			}
		}

		// Add to the underlying lens graphic system.
		this.generalAppealOverlay.addPlots(this.naturalWonderPlots, { fillColor: NATURAL_WONDER_COLOR });
		this.generalAppealOverlay.addPlots(this.breathtakingPlots, { fillColor: BREATHTAKING_COLOR });
		this.generalAppealOverlay.addPlots(this.charmingPlots, { fillColor: CHARMING_COLOR });
		this.generalAppealOverlay.addPlots(this.averagePlots, { fillColor: AVERAGE_COLOR });

		// Tell the world about this event.
		window.dispatchEvent(new ToggleGeneralAppealPanelEvent(true));
	}

	removeLayer() {
		window.dispatchEvent(new ToggleGeneralAppealPanelEvent(false));
		this.clearOverlay();
	}
}

declare global {
	interface LensLayerTypeMap {
		"fxs-general-appeal-layer": GeneralAppealLensLayer;
	}
}

LensManager.registerLensLayer("fxs-general-appeal-layer", new GeneralAppealLensLayer());
